{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Niraparib, a structurally related heteroaromatic amide with a basic amine, had absolute oral bioavailability of 72.7% (90% CI 61.69-83.40) in cancer patients, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "ZL-2201, a heteroaromatic amino-pyrimidine with an N-alkyl group, was predicted to have approximately 70% human oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Cilomilast, containing a cyclopentyl ether and polar groups, was almost completely bioavailable (mean 96%, range 92-102%) after oral administration in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Pimodivir, an amino-pyridine heteroaromatic, had approximately 46% oral bioavailability in humans, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide, the highest-transfer analogue, had absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F >= 20% despite interindividual variability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alfuzosin, an amide-containing basic drug, had absolute oral bioavailability of 64.5% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Cabotegravir, containing a piperazine and fused aromatic system, showed near-complete oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with direct human oral bioavailability data point to F >= 20%, with most reporting values from 46% to near-complete and encainide around 30-42%. The query's favorable physicochemical profile and structural similarity to these high-bioavailability compounds reinforce the prediction. No affirmative evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the exact query molecule.",
    "Encainide shows wide interindividual bioavailability variability (range 7-82%), and some patients may have low F, though the mean supports the high threshold.",
    "Exact transporter and metabolic stability effects for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

